cases.bad:
/* Select.module.css */
.menu {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;  /* ← locks width to trigger width (~40-80px) → long options clipped */
}

cases.good:
/* Select.module.css */
.menu { width: max-content; min-width: 100%; max-width: 320px; ... }
.menuAlignLeft  { left: 0; }
.menuAlignRight { right: 0; left: auto; }

// Component prop: menuAlign?: 'left' | 'right' (default 'left')
// Right-aligned trigger passes menuAlign="right" → menu opens left, stays in container
